input.script:
services = list_services({})
counts = for svc in services {
    logs = search_logs({ service: svc, level: "ERROR", page: 1 })
    first_ts = if logs.items != [] { return logs.items[0].ts } else { return "" }
    return { service: svc, total_errors: logs.total_items, total_pages: logs.total_pages, first_ts: first_ts }
}
return counts

services = boundary retry 3 {
    return list_services({})
} catch err {
    return fail("LIST_FAILED", err.message)
}
counts = for svc in services {
    logs = boundary retry 3 {
        return search_logs({ service: svc, level: "ERROR", page: 1 })
    } catch err {
        return fail("LOGS_FAILED", err.message)
    }
    first_ts = if logs.items != [] { return logs.items[0].ts } else { return "" }
    return { service: svc, total_errors: logs.total_items, total_pages: logs.total_pages, first_ts: first_ts }
}
return counts

deploys = boundary retry 3 {
    return get_deploys({ service: "payments" })
} catch err {
    return fail("DEPLOYS_FAILED", err.message)
}
owner = boundary retry 3 {
    return get_service_owners({ service: "payments" })
} catch err {
    return fail("OWNER_FAILED", err.message)
}
pages = for p in list.range(1, 3) {
    logs = boundary retry 3 {
        return search_logs({ service: "payments", level: "ERROR", page: p })
    } catch err {
        return fail("LOGS_FAILED", err.message)
    }
    return logs.items
}
entries = fold acc = [] for page in pages { return acc + page }
ts_list = for e in entries { return e.ts }
return { deploys: deploys, owner: owner, error_timestamps: ts_list, messages: for e in list.slice(entries, 0, 5) { return e.message } }
